// Markdown renderer: CommonMark block/inline algorithm (modelled on the
// parsing strategy described in the CommonMark spec appendix and used by
// commonmark.js) plus GFM pipe tables, ~~strikethrough~~ and [[wiki links]].
// Written from scratch for this project (see PROVENANCE.json).

import { decodeEntity } from './entities.js';

// ---------------------------------------------------------------- utilities

const ESCAPABLE = '[!"#$%&\'()*+,./:;<=>?@[\\\\\\]^_`{|}~-]';
const reEscapable = new RegExp('^' + ESCAPABLE);
const reEntityOrEscaped = new RegExp('\\\\' + ESCAPABLE + '|&(?:#[xX][a-fA-F0-9]{1,6}|#[0-9]{1,7}|[a-zA-Z][a-zA-Z0-9]{1,31});', 'g');
const reEntityHere = /^&(?:#[xX][a-fA-F0-9]{1,6}|#[0-9]{1,7}|[a-zA-Z][a-zA-Z0-9]{1,31});/;

export function escapeHtml(s) {
  return String(s).replace(/[&<>"]/g, c => (c === '&' ? '&amp;' : c === '<' ? '&lt;' : c === '>' ? '&gt;' : '&quot;'));
}

function unescapeString(s) {
  return s.replace(reEntityOrEscaped, m => (m[0] === '\\' ? m.slice(1) : decodeEntity(m)));
}

function normalizeURI(uri) {
  let out = '';
  for (let i = 0; i < uri.length; i++) {
    const c = uri[i];
    if (c === '%' && /^[0-9a-fA-F]{2}$/.test(uri.slice(i + 1, i + 3))) { out += uri.slice(i, i + 3); i += 2; continue; }
    if (/[A-Za-z0-9;/?:@&=+$,\-_.!~*'()#]/.test(c)) { out += c; continue; }
    const cp = uri.codePointAt(i);
    if (cp > 0xffff) i++;
    try { out += encodeURIComponent(String.fromCodePoint(cp)); } catch { out += '%EF%BF%BD'; }
  }
  return out;
}

function normalizeReference(s) {
  return s.slice(1, s.length - 1).trim().replace(/[ \t\r\n]+/g, ' ').toLowerCase().toUpperCase();
}

const reUnsafeScheme = /^(?:javascript|vbscript|file|data):/i;
const reSafeData = /^data:image\/(?:png|gif|jpeg|webp);/i;
function safeUrl(url) {
  const probe = url.replace(/^[\s\x00-\x20]+/, '').replace(/[\t\n\r]/g, '');
  let decoded = probe;
  try { decoded = decodeURIComponent(probe); } catch { /* keep */ }
  for (const u of [probe, decoded]) {
    if (reUnsafeScheme.test(u) && !reSafeData.test(u)) return '#';
  }
  return url;
}

/**
 * GitHub-style slug. With a Map `seen`, duplicates get -1, -2, ...
 */
export function slugify(text, seen) {
  let base = String(text).toLowerCase().replace(/[^\p{L}\p{N} _-]/gu, '').replace(/ /g, '-');
  if (!seen) return base;
  if (!seen.has(base)) { seen.set(base, 0); return base; }
  let n = seen.get(base);
  let cand;
  do { n += 1; cand = `${base}-${n}`; } while (seen.has(cand));
  seen.set(base, n);
  seen.set(cand, 0);
  return cand;
}

// --------------------------------------------------------------------- nodes

class Node {
  constructor(type, startLine = 0) {
    this.type = type;
    this.parent = null; this.firstChild = null; this.lastChild = null; this.prev = null; this.next = null;
    this.open = true;
    this.string = '';
    this.literal = '';
    this.startLine = startLine;
    this.lastLineBlank = false;
    this.lastLineChecked = false;
  }
  appendChild(child) {
    child.unlink();
    child.parent = this;
    if (this.lastChild) { this.lastChild.next = child; child.prev = this.lastChild; this.lastChild = child; } else { this.firstChild = this.lastChild = child; }
  }
  unlink() {
    if (this.prev) this.prev.next = this.next; else if (this.parent) this.parent.firstChild = this.next;
    if (this.next) this.next.prev = this.prev; else if (this.parent) this.parent.lastChild = this.prev;
    this.parent = this.next = this.prev = null;
  }
  insertAfter(sibling) {
    sibling.unlink();
    sibling.next = this.next;
    if (sibling.next) sibling.next.prev = sibling;
    sibling.prev = this; this.next = sibling; sibling.parent = this.parent;
    if (!sibling.next && sibling.parent) sibling.parent.lastChild = sibling;
  }
  insertBefore(sibling) {
    sibling.unlink();
    sibling.prev = this.prev;
    if (sibling.prev) sibling.prev.next = sibling;
    sibling.next = this; this.prev = sibling; sibling.parent = this.parent;
    if (!sibling.prev && sibling.parent) sibling.parent.firstChild = sibling;
  }
  *children() { for (let c = this.firstChild; c; c = c.next) yield c; }
}

function textNode(s) { const n = new Node('text'); n.literal = s; return n; }

// ------------------------------------------------------------- block parser

const CODE_INDENT = 4;
const reNonSpace = /[^ \t\f\v\r\n]/;
const reBulletListMarker = /^[*+-]/;
const reOrderedListMarker = /^(\d{1,9})([.)])/;
const reATXHeadingMarker = /^#{1,6}(?:[ \t]+|$)/;
const reCodeFence = /^`{3,}(?!.*`)|^~{3,}/;
const reClosingCodeFence = /^(?:`{3,}|~{3,})(?=[ \t]*$)/;
const reSetextHeadingLine = /^(?:=+|-+)[ \t]*$/;
const reThematicBreak = /^(?:\*[ \t]*){3,}$|^(?:_[ \t]*){3,}$|^(?:-[ \t]*){3,}$/;
const reTableDelimRow = /^\|?[ \t]*:?-+:?[ \t]*(?:\|[ \t]*:?-+:?[ \t]*)*\|?[ \t]*$/;
const reLineEnding = /\r\n|\n|\r/;

const isSpaceOrTab = c => c === ' ' || c === '\t';
const isBlank = s => !reNonSpace.test(s);

function splitTableRow(line) {
  let s = line.trim();
  if (s.startsWith('|')) s = s.slice(1);
  if (s.endsWith('|') && !s.endsWith('\\|')) s = s.slice(0, -1);
  const cells = [];
  let cur = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '\\' && s[i + 1] === '|') { cur += '|'; i++; continue; }
    if (c === '\\' && i + 1 < s.length) { cur += c + s[i + 1]; i++; continue; }
    if (c === '|') { cells.push(cur.trim()); cur = ''; continue; }
    cur += c;
  }
  cells.push(cur.trim());
  return cells;
}

function startsOtherBlock(rest) {
  return rest[0] === '>' || reATXHeadingMarker.test(rest) || reCodeFence.test(rest) || reThematicBreak.test(rest);
}

const blocks = {
  document: {
    continue: () => 0,
    finalize: () => {},
    canContain: t => t !== 'item',
    acceptsLines: false,
  },
  list: {
    continue: () => 0,
    finalize: (p, block) => {
      let item = block.firstChild;
      while (item) {
        if (endsWithBlankLine(item) && item.next) { block.listData.tight = false; break; }
        let sub = item.firstChild;
        while (sub) {
          if (endsWithBlankLine(sub) && (item.next || sub.next)) { block.listData.tight = false; break; }
          sub = sub.next;
        }
        if (!block.listData.tight) break;
        item = item.next;
      }
    },
    canContain: t => t === 'item',
    acceptsLines: false,
  },
  block_quote: {
    continue: (p) => {
      const ln = p.currentLine;
      if (!p.indented && ln[p.nextNonspace] === '>') {
        p.advanceNextNonspace();
        p.advanceOffset(1, false);
        if (isSpaceOrTab(ln[p.offset])) p.advanceOffset(1, true);
        return 0;
      }
      return 1;
    },
    finalize: () => {},
    canContain: t => t !== 'item',
    acceptsLines: false,
  },
  item: {
    continue: (p, container) => {
      if (p.blank) {
        if (container.firstChild == null) return 1;
        p.advanceNextNonspace();
      } else if (p.indent >= container.listData.markerOffset + container.listData.padding) {
        p.advanceOffset(container.listData.markerOffset + container.listData.padding, true);
      } else return 1;
      return 0;
    },
    finalize: () => {},
    canContain: t => t !== 'item',
    acceptsLines: false,
  },
  heading: {
    continue: () => 1,
    finalize: () => {},
    canContain: () => false,
    acceptsLines: false,
  },
  thematic_break: {
    continue: () => 1,
    finalize: () => {},
    canContain: () => false,
    acceptsLines: false,
  },
  code_block: {
    continue: (p, container) => {
      const ln = p.currentLine;
      const indent = p.indent;
      if (container.isFenced) {
        const m = indent <= 3 && ln[p.nextNonspace] === container.fenceChar && ln.slice(p.nextNonspace).match(reClosingCodeFence);
        if (m && m[0].length >= container.fenceLength) {
          p.finalize(container, p.lineNumber);
          return 2;
        }
        let i = container.fenceOffset;
        while (i > 0 && isSpaceOrTab(ln[p.offset])) { p.advanceOffset(1, true); i--; }
      } else if (indent >= CODE_INDENT) {
        p.advanceOffset(CODE_INDENT, true);
      } else if (p.blank) {
        p.advanceNextNonspace();
      } else return 1;
      return 0;
    },
    finalize: (p, block) => {
      if (block.isFenced) {
        const content = block.string;
        const nl = content.indexOf('\n');
        const firstLine = content.slice(0, nl);
        block.info = unescapeString(firstLine.trim());
        block.literal = content.slice(nl + 1);
      } else {
        block.literal = block.string.replace(/(\n *)+$/, '\n');
      }
      block.string = '';
    },
    canContain: () => false,
    acceptsLines: true,
  },
  paragraph: {
    continue: p => (p.blank ? 1 : 0),
    finalize: (p, block) => {
      let pos;
      let hasRefs = false;
      while (block.string[0] === '[' && (pos = p.inline.parseReference(block.string, p.refmap))) {
        block.string = block.string.slice(pos);
        hasRefs = true;
      }
      if (hasRefs && isBlank(block.string)) block.unlink();
    },
    canContain: () => false,
    acceptsLines: true,
  },
  table: {
    continue: (p) => {
      if (p.blank) return 1;
      if (p.indent < CODE_INDENT && startsOtherBlock(p.currentLine.slice(p.nextNonspace))) return 1;
      return 0;
    },
    finalize: (p, block) => {
      const lines = block.string.split('\n').filter(l => l !== '');
      const header = splitTableRow(lines[0]);
      const aligns = splitTableRow(lines[1]).map(c => {
        const l = c.startsWith(':'); const r = c.endsWith(':');
        return l && r ? 'center' : l ? 'left' : r ? 'right' : '';
      });
      block.aligns = aligns;
      block.header = header;
      block.rows = lines.slice(2).map(l => {
        const cells = splitTableRow(l);
        const out = [];
        for (let i = 0; i < header.length; i++) out.push(cells[i] ?? '');
        return out;
      });
      block.string = '';
    },
    canContain: () => false,
    acceptsLines: true,
  },
};

function endsWithBlankLine(block) {
  while (block) {
    if (block.lastLineBlank) return true;
    const t = block.type;
    if (!block.lastLineChecked && (t === 'list' || t === 'item')) {
      block.lastLineChecked = true;
      block = block.lastChild;
    } else {
      block.lastLineChecked = true;
      break;
    }
  }
  return false;
}

function parseListMarker(p, container) {
  const rest = p.currentLine.slice(p.nextNonspace);
  let m;
  const data = { type: null, tight: true, bulletChar: null, start: null, delimiter: null, padding: null, markerOffset: p.indent };
  if (p.indent >= 4) return null;
  if ((m = rest.match(reBulletListMarker))) {
    data.type = 'bullet'; data.bulletChar = m[0][0];
  } else if ((m = rest.match(reOrderedListMarker)) && (container.type !== 'paragraph' || m[1] === '1')) {
    data.type = 'ordered'; data.start = parseInt(m[1], 10); data.delimiter = m[2];
  } else return null;
  let nextc = p.currentLine[p.nextNonspace + m[0].length];
  if (!(nextc === undefined || nextc === '\t' || nextc === ' ')) return null;
  if (container.type === 'paragraph' && !reNonSpace.test(p.currentLine.slice(p.nextNonspace + m[0].length))) return null;
  p.advanceNextNonspace();
  p.advanceOffset(m[0].length, true);
  const spacesStartCol = p.column;
  const spacesStartOffset = p.offset;
  do {
    p.advanceOffset(1, true);
    nextc = p.currentLine[p.offset];
  } while (p.column - spacesStartCol < 5 && isSpaceOrTab(nextc));
  const blankItem = p.currentLine[p.offset] === undefined;
  const spacesAfterMarker = p.column - spacesStartCol;
  if (spacesAfterMarker >= 5 || spacesAfterMarker < 1 || blankItem) {
    data.padding = m[0].length + 1;
    p.column = spacesStartCol;
    p.offset = spacesStartOffset;
    if (isSpaceOrTab(p.currentLine[p.offset])) p.advanceOffset(1, true);
  } else {
    data.padding = m[0].length + spacesAfterMarker;
  }
  return data;
}

const listsMatch = (a, b) => a.type === b.type && a.delimiter === b.delimiter && a.bulletChar === b.bulletChar;

const blockStarts = [
  // block quote
  (p) => {
    if (!p.indented && p.currentLine[p.nextNonspace] === '>') {
      p.advanceNextNonspace();
      p.advanceOffset(1, false);
      if (isSpaceOrTab(p.currentLine[p.offset])) p.advanceOffset(1, true);
      p.closeUnmatchedBlocks();
      p.addChild('block_quote', p.nextNonspace);
      return 1;
    }
    return 0;
  },
  // ATX heading
  (p) => {
    let m;
    if (!p.indented && (m = p.currentLine.slice(p.nextNonspace).match(reATXHeadingMarker))) {
      p.advanceNextNonspace();
      p.advanceOffset(m[0].length, false);
      p.closeUnmatchedBlocks();
      const c = p.addChild('heading', p.nextNonspace);
      c.level = m[0].trim().length;
      c.string = p.currentLine.slice(p.offset).replace(/^[ \t]*#+[ \t]*$/, '').replace(/[ \t]+#+[ \t]*$/, '');
      p.advanceOffset(p.currentLine.length - p.offset);
      return 2;
    }
    return 0;
  },
  // fenced code
  (p) => {
    let m;
    if (!p.indented && (m = p.currentLine.slice(p.nextNonspace).match(reCodeFence))) {
      const fenceLength = m[0].length;
      p.closeUnmatchedBlocks();
      const c = p.addChild('code_block', p.nextNonspace);
      c.isFenced = true;
      c.fenceLength = fenceLength;
      c.fenceChar = m[0][0];
      c.fenceOffset = p.indent;
      p.advanceNextNonspace();
      p.advanceOffset(fenceLength, false);
      return 2;
    }
    return 0;
  },
  // GFM table (delimiter row following a paragraph line)
  (p, container) => {
    if (p.indented || container.type !== 'paragraph') return 0;
    const rest = p.currentLine.slice(p.nextNonspace);
    if (!rest.includes('|') && !container.string.includes('|')) return 0;
    if (!reTableDelimRow.test(rest)) return 0;
    const lines = container.string.replace(/\n$/, '').split('\n');
    const headerLine = lines[lines.length - 1];
    const delimCells = splitTableRow(rest);
    const headerCells = splitTableRow(headerLine);
    if (headerCells.length !== delimCells.length) return 0;
    p.closeUnmatchedBlocks();
    const table = new Node('table', p.lineNumber - 1);
    table.string = headerLine + '\n' + rest + '\n';
    if (lines.length > 1) {
      container.string = lines.slice(0, -1).join('\n') + '\n';
      container.insertAfter(table);
      p.finalize(container, p.lineNumber - 1);
    } else {
      // attempt to keep reference definitions semantics: header was the only line
      container.insertAfter(table);
      container.unlink();
    }
    p.tip = table;
    p.advanceOffset(p.currentLine.length - p.offset, false);
    return 2;
  },
  // setext heading
  (p, container) => {
    let m;
    if (!p.indented && container.type === 'paragraph' && (m = p.currentLine.slice(p.nextNonspace).match(reSetextHeadingLine))) {
      p.closeUnmatchedBlocks();
      let pos;
      while (container.string[0] === '[' && (pos = p.inline.parseReference(container.string, p.refmap))) {
        container.string = container.string.slice(pos);
      }
      if (container.string.length > 0) {
        const heading = new Node('heading', container.startLine);
        heading.level = m[0][0] === '=' ? 1 : 2;
        heading.string = container.string;
        container.insertAfter(heading);
        container.unlink();
        p.tip = heading;
        p.advanceOffset(p.currentLine.length - p.offset, false);
        return 2;
      }
      return 0;
    }
    return 0;
  },
  // thematic break
  (p) => {
    if (!p.indented && reThematicBreak.test(p.currentLine.slice(p.nextNonspace))) {
      p.closeUnmatchedBlocks();
      p.addChild('thematic_break', p.nextNonspace);
      p.advanceOffset(p.currentLine.length - p.offset, false);
      return 2;
    }
    return 0;
  },
  // list item
  (p, container) => {
    let data;
    if ((!p.indented || container.type === 'list') && (data = parseListMarker(p, container))) {
      p.closeUnmatchedBlocks();
      if (p.tip.type !== 'list' || !listsMatch(container.listData, data)) {
        const list = p.addChild('list', p.nextNonspace);
        list.listData = data;
      }
      const item = p.addChild('item', p.nextNonspace);
      item.listData = data;
      return 1;
    }
    return 0;
  },
  // indented code
  (p) => {
    if (p.indented && p.tip.type !== 'paragraph' && !p.blank) {
      p.advanceOffset(CODE_INDENT, true);
      p.closeUnmatchedBlocks();
      p.addChild('code_block', p.offset);
      return 2;
    }
    return 0;
  },
];

const reMaybeSpecial = /^[#`~*+_=<>0-9|-]/;

class BlockParser {
  constructor(options) {
    this.options = options;
    this.inline = new InlineParser(options);
  }

  parse(input) {
    this.doc = new Node('document', 0);
    this.tip = this.doc;
    this.oldtip = this.doc;
    this.refmap = {};
    this.lineNumber = 0;
    this.lastMatchedContainer = this.doc;
    this.allClosed = true;
    const lines = input.split(reLineEnding);
    let len = lines.length;
    if (input.length > 0 && /[\n\r]$/.test(input)) len -= 1;
    for (let i = 0; i < len; i++) this.incorporateLine(lines[i]);
    while (this.tip) this.finalize(this.tip, len);
    this.processInlines(this.doc);
    return this.doc;
  }

  findNextNonspace() {
    const ln = this.currentLine;
    let i = this.offset;
    let cols = this.column;
    let c;
    while ((c = ln[i]) !== undefined) {
      if (c === ' ') { i++; cols++; } else if (c === '\t') { i++; cols += 4 - (cols % 4); } else break;
    }
    this.blank = c === undefined || c === '\n' || c === '\r';
    this.nextNonspace = i;
    this.nextNonspaceColumn = cols;
    this.indent = cols - this.column;
    this.indented = this.indent >= CODE_INDENT;
  }

  advanceOffset(count, columns) {
    const ln = this.currentLine;
    let c;
    while (count > 0 && (c = ln[this.offset]) !== undefined) {
      if (c === '\t') {
        const charsToTab = 4 - (this.column % 4);
        if (columns) {
          this.partiallyConsumedTab = charsToTab > count;
          const adv = charsToTab > count ? count : charsToTab;
          this.column += adv;
          this.offset += this.partiallyConsumedTab ? 0 : 1;
          count -= adv;
        } else {
          this.partiallyConsumedTab = false;
          this.column += charsToTab;
          this.offset += 1;
          count -= 1;
        }
      } else {
        this.partiallyConsumedTab = false;
        this.offset += 1;
        this.column += 1;
        count -= 1;
      }
    }
  }

  advanceNextNonspace() {
    this.offset = this.nextNonspace;
    this.column = this.nextNonspaceColumn;
    this.partiallyConsumedTab = false;
  }

  addLine() {
    if (this.partiallyConsumedTab) {
      this.offset += 1;
      const charsToTab = 4 - (this.column % 4);
      this.tip.string += ' '.repeat(charsToTab);
    }
    this.tip.string += this.currentLine.slice(this.offset) + '\n';
  }

  addChild(tag) {
    while (!blocks[this.tip.type].canContain(tag)) this.finalize(this.tip, this.lineNumber - 1);
    const node = new Node(tag, this.lineNumber);
    this.tip.appendChild(node);
    this.tip = node;
    return node;
  }

  closeUnmatchedBlocks() {
    if (!this.allClosed) {
      while (this.oldtip !== this.lastMatchedContainer) {
        const parent = this.oldtip.parent;
        this.finalize(this.oldtip, this.lineNumber - 1);
        this.oldtip = parent;
      }
      this.allClosed = true;
    }
  }

  finalize(block) {
    const above = block.parent;
    block.open = false;
    blocks[block.type].finalize(this, block);
    this.tip = above;
  }

  incorporateLine(ln) {
    let allMatched = true;
    let container = this.doc;
    this.oldtip = this.tip;
    this.offset = 0;
    this.column = 0;
    this.blank = false;
    this.partiallyConsumedTab = false;
    this.lineNumber += 1;
    if (ln.indexOf('\u0000') !== -1) ln = ln.replace(/\0/g, '�');
    this.currentLine = ln;

    let lastChild;
    while ((lastChild = container.lastChild) && lastChild.open) {
      container = lastChild;
      this.findNextNonspace();
      const r = blocks[container.type].continue(this, container);
      if (r === 2) return;
      if (r === 1) { allMatched = false; container = container.parent; break; }
    }

    this.allClosed = container === this.oldtip;
    this.lastMatchedContainer = container;

    let matchedLeaf = container.type !== 'paragraph' && blocks[container.type].acceptsLines;

    while (!matchedLeaf) {
      this.findNextNonspace();
      if (!this.indented && !reMaybeSpecial.test(ln.slice(this.nextNonspace))) {
        this.advanceNextNonspace();
        break;
      }
      let i = 0;
      for (; i < blockStarts.length; i++) {
        const res = blockStarts[i](this, container);
        if (res === 1) { container = this.tip; break; }
        if (res === 2) { container = this.tip; matchedLeaf = true; break; }
      }
      if (i === blockStarts.length) { this.advanceNextNonspace(); break; }
    }

    if (!this.allClosed && !this.blank && this.tip.type === 'paragraph') {
      this.addLine();
    } else {
      this.closeUnmatchedBlocks();
      if (this.blank && container.lastChild) container.lastChild.lastLineBlank = true;
      const t = container.type;
      const lastLineBlank = this.blank && !(t === 'block_quote' || (t === 'code_block' && container.isFenced) ||
        (t === 'item' && !container.firstChild && container.startLine === this.lineNumber));
      let cont = container;
      while (cont) { cont.lastLineBlank = lastLineBlank; cont = cont.parent; }
      if (blocks[t].acceptsLines) {
        this.addLine();
      } else if (this.offset < ln.length && !this.blank) {
        this.addChild('paragraph', this.offset);
        this.advanceNextNonspace();
        this.addLine();
      }
    }
  }

  processInlines(node) {
    const walk = (n) => {
      if (n.type === 'paragraph' || n.type === 'heading') {
        this.inline.parse(n, n.string, this.refmap);
      } else if (n.type === 'table') {
        n.headerNodes = n.header.map(c => { const cell = new Node('cell'); this.inline.parse(cell, c, this.refmap); return cell; });
        n.rowNodes = n.rows.map(r => r.map(c => { const cell = new Node('cell'); this.inline.parse(cell, c, this.refmap); return cell; }));
      }
      for (let c = n.firstChild; c; c = c.next) walk(c);
    };
    walk(node);
  }
}

// ------------------------------------------------------------ inline parser

const reWhitespaceChar = /^[ \t\n\x0b\x0c\x0d]/;
const reUnicodeWhitespace = /^\s/u;
const rePunctuation = /^[\p{P}\p{S}]/u;
const reLinkTitle = /^(?:"((?:\\[\s\S]|[^"\\\x00])*)"|'((?:\\[\s\S]|[^'\\\x00])*)'|\(((?:\\[\s\S]|[^()\\\x00])*)\))/;
const reLinkDestinationBraces = /^<(?:[^<>\n\\\x00]|\\.)*>/;
const reLinkLabel = /^\[(?:[^\\[\]]|\\[\s\S]){0,1000}\]/;
const reEmailAutolink = /^<([a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*)>/;
const reAutolink = /^<[A-Za-z][A-Za-z0-9.+-]{1,31}:[^<>\x00-\x20]*>/;
const reSpnl = /^[ \t]*(?:\n[ \t]*)?/;
const reSpaceAtEndOfLine = /^[ \t]*(?:\n|$)/;
const reMain = /^[^\n`[\]\\!<&*_~]+/;
const reWiki = /^\[\[([^[\]\n|]+)(?:\|([^[\]\n]+))?\]\]/;

class InlineParser {
  constructor(options) { this.options = options || {}; }

  peek() { return this.pos < this.subject.length ? this.subject[this.pos] : undefined; }

  match(re) {
    const m = re.exec(this.subject.slice(this.pos));
    if (m === null) return null;
    this.pos += m.index + m[0].length;
    return m[0];
  }

  spnl() { this.match(reSpnl); return true; }

  parse(block, content, refmap) {
    this.subject = content.trim();
    this.pos = 0;
    this.delimiters = null;
    this.brackets = null;
    this.refmap = refmap;
    while (this.parseInline(block));
    this.processEmphasis(null);
  }

  parseInline(block) {
    const c = this.peek();
    if (c === undefined) return false;
    let res = false;
    switch (c) {
      case '\n': res = this.parseNewline(block); break;
      case '\\': res = this.parseBackslash(block); break;
      case '`': res = this.parseBackticks(block); break;
      case '*': case '_': case '~': res = this.handleDelim(c, block); break;
      case '[': res = this.parseWikiLink(block) || this.parseOpenBracket(block); break;
      case '!': res = this.parseBang(block); break;
      case ']': res = this.parseCloseBracket(block); break;
      case '<': res = this.parseAutolink(block); break;
      case '&': res = this.parseEntity(block); break;
      default: res = this.parseString(block);
    }
    if (!res) {
      this.pos += 1;
      block.appendChild(textNode(c));
    }
    return true;
  }

  parseString(block) {
    const m = this.match(reMain);
    if (m === null) return false;
    block.appendChild(textNode(m));
    return true;
  }

  parseNewline(block) {
    this.pos += 1;
    const last = block.lastChild;
    if (last && last.type === 'text' && last.literal[last.literal.length - 1] === ' ') {
      const hard = last.literal[last.literal.length - 2] === ' ';
      last.literal = last.literal.replace(/ *$/, '');
      block.appendChild(new Node(hard ? 'linebreak' : 'softbreak'));
    } else {
      block.appendChild(new Node('softbreak'));
    }
    this.match(/^[ \t]*/);
    return true;
  }

  parseBackslash(block) {
    this.pos += 1;
    const c = this.peek();
    if (c === '\n') {
      this.pos += 1;
      block.appendChild(new Node('linebreak'));
      this.match(/^[ \t]*/);
    } else if (c !== undefined && reEscapable.test(c)) {
      block.appendChild(textNode(c));
      this.pos += 1;
    } else {
      block.appendChild(textNode('\\'));
    }
    return true;
  }

  parseBackticks(block) {
    const ticks = this.match(/^`+/);
    if (ticks === null) return false;
    const after = this.pos;
    let m;
    while ((m = this.match(/`+/)) !== null) {
      if (m === ticks) {
        let contents = this.subject.slice(after, this.pos - ticks.length).replace(/\n/g, ' ');
        if (contents.length > 0 && /[^ ]/.test(contents) && contents[0] === ' ' && contents[contents.length - 1] === ' ') {
          contents = contents.slice(1, -1);
        }
        const node = new Node('code');
        node.literal = contents;
        block.appendChild(node);
        return true;
      }
    }
    this.pos = after;
    block.appendChild(textNode(ticks));
    return true;
  }

  scanDelims(cc) {
    let n = 0;
    const start = this.pos;
    while (this.peek() === cc) { n++; this.pos++; }
    if (n === 0) return null;
    const before = start === 0 ? '\n' : String.fromCodePoint(this.subject.codePointAt(start - 1) >= 0xdc00 && this.subject.codePointAt(start - 1) <= 0xdfff && start >= 2 ? this.subject.codePointAt(start - 2) : this.subject.codePointAt(start - 1));
    const after = this.pos < this.subject.length ? String.fromCodePoint(this.subject.codePointAt(this.pos)) : '\n';
    const afterWs = reUnicodeWhitespace.test(after);
    const afterP = rePunctuation.test(after);
    const beforeWs = reUnicodeWhitespace.test(before);
    const beforeP = rePunctuation.test(before);
    const left = !afterWs && (!afterP || beforeWs || beforeP);
    const right = !beforeWs && (!beforeP || afterWs || afterP);
    let canOpen, canClose;
    if (cc === '_') {
      canOpen = left && (!right || beforeP);
      canClose = right && (!left || afterP);
    } else {
      canOpen = left;
      canClose = right;
    }
    if (cc === '~' && n > 2) { canOpen = false; canClose = false; }
    this.pos = start;
    return { n, canOpen, canClose };
  }

  handleDelim(cc, block) {
    const res = this.scanDelims(cc);
    if (!res) return false;
    const start = this.pos;
    this.pos += res.n;
    const node = textNode(this.subject.slice(start, this.pos));
    block.appendChild(node);
    if (res.canOpen || res.canClose) {
      this.delimiters = { cc, numdelims: res.n, origdelims: res.n, node, previous: this.delimiters, next: null, canOpen: res.canOpen, canClose: res.canClose };
      if (this.delimiters.previous) this.delimiters.previous.next = this.delimiters;
    }
    return true;
  }

  removeDelimiter(d) {
    if (d.previous !== null) d.previous.next = d.next;
    if (d.next !== null) d.next.previous = d.previous;
    else this.delimiters = d.previous;
  }

  processEmphasis(stackBottom) {
    const openersBottom = { '*': [], '_': [], '~': [] };
    for (const k of Object.keys(openersBottom)) for (let i = 0; i < 6; i++) openersBottom[k][i] = stackBottom;
    let closer = this.delimiters;
    while (closer !== null && closer.previous !== stackBottom) closer = closer.previous;
    while (closer !== null) {
      if (!closer.canClose) { closer = closer.next; continue; }
      const cc = closer.cc;
      const idx = cc === '~' ? closer.origdelims : (closer.canOpen ? 3 : 0) + (closer.origdelims % 3);
      let opener = closer.previous;
      let found = false;
      while (opener !== null && opener !== stackBottom && opener !== openersBottom[cc][idx]) {
        if (cc === '~') {
          if (opener.cc === '~' && opener.canOpen && opener.origdelims === closer.origdelims) { found = true; break; }
        } else {
          const oddMatch = (closer.canOpen || opener.canClose) && closer.origdelims % 3 !== 0 && (opener.origdelims + closer.origdelims) % 3 === 0;
          if (opener.cc === cc && opener.canOpen && !oddMatch) { found = true; break; }
        }
        opener = opener.previous;
      }
      const oldCloser = closer;
      if (!found) {
        closer = closer.next;
      } else {
        const use = cc === '~' ? closer.numdelims : (closer.numdelims >= 2 && opener.numdelims >= 2 ? 2 : 1);
        const oi = opener.node; const ci = closer.node;
        opener.numdelims -= use; closer.numdelims -= use;
        oi.literal = oi.literal.slice(0, oi.literal.length - use);
        ci.literal = ci.literal.slice(0, ci.literal.length - use);
        const wrap = new Node(cc === '~' ? 'del' : use === 1 ? 'emph' : 'strong');
        let tmp = oi.next;
        while (tmp && tmp !== ci) { const nx = tmp.next; wrap.appendChild(tmp); tmp = nx; }
        oi.insertAfter(wrap);
        // remove delimiters between opener and closer
        if (closer.previous !== opener) { opener.next = closer; closer.previous = opener; }
        if (opener.numdelims === 0) { oi.unlink(); this.removeDelimiter(opener); }
        if (closer.numdelims === 0) { ci.unlink(); const nx = closer.next; this.removeDelimiter(closer); closer = nx; }
      }
      if (!found) {
        openersBottom[cc][idx] = oldCloser.previous;
        if (!oldCloser.canOpen) this.removeDelimiter(oldCloser);
      }
    }
    while (this.delimiters !== null && this.delimiters !== stackBottom) this.removeDelimiter(this.delimiters);
  }

  parseWikiLink(block) {
    if (!this.options.wikiLinks || this.subject[this.pos + 1] !== '[') return false;
    const m = reWiki.exec(this.subject.slice(this.pos));
    if (!m) return false;
    const target = m[1].trim();
    if (!target) return false;
    const label = m[2] !== undefined ? m[2].trim() : target;
    this.pos += m[0].length;
    const node = new Node('wikilink');
    node.target = target;
    node.slug = slugify(target);
    node.label = label || target;
    block.appendChild(node);
    return true;
  }

  addBracket(node, index, image) {
    if (this.brackets !== null) this.brackets.bracketAfter = true;
    this.brackets = { node, previous: this.brackets, previousDelimiter: this.delimiters, index, image, active: true, bracketAfter: false };
  }

  parseOpenBracket(block) {
    const start = this.pos;
    this.pos += 1;
    const node = textNode('[');
    block.appendChild(node);
    this.addBracket(node, start, false);
    return true;
  }

  parseBang(block) {
    const start = this.pos;
    this.pos += 1;
    if (this.peek() === '[') {
      this.pos += 1;
      const node = textNode('![');
      block.appendChild(node);
      this.addBracket(node, start + 1, true);
    } else {
      block.appendChild(textNode('!'));
    }
    return true;
  }

  parseLinkDestination() {
    const res = this.match(reLinkDestinationBraces);
    if (res !== null) return normalizeURI(unescapeString(res.slice(1, -1)));
    if (this.peek() === '<') return null;
    const save = this.pos;
    let open = 0;
    let c;
    while ((c = this.peek()) !== undefined) {
      if (c === '\\' && reEscapable.test(this.subject[this.pos + 1] || '')) {
        this.pos += 2;
      } else if (c === '(') {
        this.pos += 1; open += 1;
      } else if (c === ')') {
        if (open < 1) break;
        this.pos += 1; open -= 1;
      } else if (reWhitespaceChar.test(c) || c.charCodeAt(0) < 0x20 || c === '\x7f') {
        break;
      } else {
        this.pos += 1;
      }
    }
    if (this.pos === save && c !== ')') return null;
    if (open !== 0) return null;
    return normalizeURI(unescapeString(this.subject.slice(save, this.pos)));
  }

  parseLinkTitle() {
    const m = reLinkTitle.exec(this.subject.slice(this.pos));
    if (!m) return null;
    this.pos += m[0].length;
    return unescapeString(m[0].slice(1, -1));
  }

  parseLinkLabel() {
    const m = this.match(reLinkLabel);
    if (m === null || m.length > 1001) return 0;
    return m.length;
  }

  parseCloseBracket(block) {
    this.pos += 1;
    const startpos = this.pos;
    let opener = this.brackets;
    if (opener === null) { block.appendChild(textNode(']')); return true; }
    if (!opener.active) { block.appendChild(textNode(']')); this.brackets = opener.previous; return true; }
    const isImage = opener.image;
    const savepos = this.pos;
    let dest; let title; let matched = false;
    if (this.peek() === '(') {
      this.pos += 1;
      this.spnl();
      if ((dest = this.parseLinkDestination()) !== null) {
        this.spnl();
        if (reWhitespaceChar.test(this.subject[this.pos - 1] || '')) title = this.parseLinkTitle();
        this.spnl();
        if (this.peek() === ')') { this.pos += 1; matched = true; }
      }
      if (!matched) this.pos = savepos;
    }
    if (!matched) {
      const before = this.pos;
      const n = this.parseLinkLabel();
      let reflabel;
      if (n > 2) reflabel = this.subject.slice(before, before + n);
      else if (!opener.bracketAfter) reflabel = this.subject.slice(opener.index, startpos);
      if (n === 0) this.pos = savepos;
      if (reflabel) {
        const link = this.refmap[normalizeReference(reflabel)];
        if (link) { dest = link.destination; title = link.title; matched = true; }
      }
    }
    if (matched) {
      const node = new Node(isImage ? 'image' : 'link');
      node.destination = dest;
      node.title = title || '';
      let tmp = opener.node.next;
      while (tmp) { const nx = tmp.next; node.appendChild(tmp); tmp = nx; }
      block.appendChild(node);
      this.processEmphasis(opener.previousDelimiter);
      this.brackets = opener.previous;
      opener.node.unlink();
      if (!isImage) {
        let o = this.brackets;
        while (o !== null) { if (!o.image) o.active = false; o = o.previous; }
      }
      return true;
    }
    this.brackets = opener.previous;
    this.pos = startpos;
    block.appendChild(textNode(']'));
    return true;
  }

  parseAutolink(block) {
    let m;
    if ((m = this.match(reEmailAutolink))) {
      const dest = m.slice(1, -1);
      const node = new Node('link');
      node.destination = normalizeURI('mailto:' + dest);
      node.title = '';
      node.appendChild(textNode(dest));
      block.appendChild(node);
      return true;
    }
    if ((m = this.match(reAutolink))) {
      const dest = m.slice(1, -1);
      const node = new Node('link');
      node.destination = normalizeURI(dest);
      node.title = '';
      node.appendChild(textNode(dest));
      block.appendChild(node);
      return true;
    }
    return false;
  }

  parseEntity(block) {
    const m = this.match(reEntityHere);
    if (!m) return false;
    block.appendChild(textNode(decodeEntity(m)));
    return true;
  }

  parseReference(s, refmap) {
    this.subject = s;
    this.pos = 0;
    const start = 0;
    const n = this.parseLinkLabel();
    if (n === 0) return 0;
    const rawlabel = this.subject.slice(0, n);
    if (this.peek() === ':') this.pos++; else { this.pos = start; return 0; }
    this.spnl();
    const dest = this.parseLinkDestination();
    if (dest === null) { this.pos = start; return 0; }
    const beforeTitle = this.pos;
    this.spnl();
    let title = null;
    if (this.pos !== beforeTitle) title = this.parseLinkTitle();
    if (title === null) { title = ''; this.pos = beforeTitle; }
    let atLineEnd = true;
    if (this.match(reSpaceAtEndOfLine) === null) {
      if (title === '') atLineEnd = false;
      else {
        title = '';
        this.pos = beforeTitle;
        atLineEnd = this.match(reSpaceAtEndOfLine) !== null;
      }
    }
    if (!atLineEnd) { this.pos = start; return 0; }
    const norm = normalizeReference(rawlabel);
    if (norm === '') { this.pos = start; return 0; }
    if (!Object.prototype.hasOwnProperty.call(refmap, norm)) refmap[norm] = { destination: dest, title };
    return this.pos - start;
  }
}

// ----------------------------------------------------------------- renderer

function plainText(node) {
  let s = '';
  for (let c = node.firstChild; c; c = c.next) {
    if (c.type === 'text' || c.type === 'code') s += c.literal;
    else if (c.type === 'softbreak' || c.type === 'linebreak') s += c.type === 'softbreak' ? '\n' : '\n';
    else if (c.type === 'wikilink') s += c.label;
    else s += plainText(c);
  }
  return s;
}

function headingText(node) {
  return plainText(node).replace(/\n/g, ' ');
}

class HtmlRenderer {
  constructor(options) {
    this.options = options;
    this.buf = '';
    this.seen = new Map();
  }

  out(s) { this.buf += s; }
  cr() { if (this.buf.length && this.buf[this.buf.length - 1] !== '\n') this.buf += '\n'; }

  renderChildren(node) { for (let c = node.firstChild; c; c = c.next) this.render(c); }

  render(node) {
    switch (node.type) {
      case 'document': this.renderChildren(node); break;
      case 'paragraph': {
        const gp = node.parent && node.parent.parent;
        if (gp && gp.type === 'list' && gp.listData.tight) { this.renderChildren(node); break; }
        this.cr(); this.out('<p>'); this.renderChildren(node); this.out('</p>'); this.cr();
        break;
      }
      case 'heading': {
        const tag = 'h' + node.level;
        this.cr();
        if (this.options.headingIds) this.out(`<${tag} id="${escapeHtml(slugify(headingText(node), this.seen))}">`);
        else this.out(`<${tag}>`);
        this.renderChildren(node);
        this.out(`</${tag}>`);
        this.cr();
        break;
      }
      case 'code_block': {
        const info = node.info ? node.info.split(/\s+/)[0] : '';
        this.cr();
        this.out(info ? `<pre><code class="language-${escapeHtml(info)}">` : '<pre><code>');
        this.out(escapeHtml(node.literal));
        this.out('</code></pre>');
        this.cr();
        break;
      }
      case 'thematic_break': this.cr(); this.out('<hr />'); this.cr(); break;
      case 'block_quote':
        this.cr(); this.out('<blockquote>'); this.cr(); this.renderChildren(node); this.cr(); this.out('</blockquote>'); this.cr();
        break;
      case 'list': {
        const d = node.listData;
        const tag = d.type === 'bullet' ? 'ul' : 'ol';
        this.cr();
        this.out(tag === 'ol' && d.start !== null && d.start !== 1 ? `<ol start="${d.start}">` : `<${tag}>`);
        this.cr();
        this.renderChildren(node);
        this.cr();
        this.out(`</${tag}>`);
        this.cr();
        break;
      }
      case 'item': this.out('<li>'); this.renderChildren(node); this.out('</li>'); this.cr(); break;
      case 'table': this.renderTable(node); break;
      case 'text': this.out(escapeHtml(node.literal)); break;
      case 'softbreak': this.out('\n'); break;
      case 'linebreak': this.out('<br />'); this.cr(); break;
      case 'code': this.out('<code>' + escapeHtml(node.literal) + '</code>'); break;
      case 'emph': this.out('<em>'); this.renderChildren(node); this.out('</em>'); break;
      case 'strong': this.out('<strong>'); this.renderChildren(node); this.out('</strong>'); break;
      case 'del': this.out('<del>'); this.renderChildren(node); this.out('</del>'); break;
      case 'link': {
        let s = `<a href="${escapeHtml(safeUrl(node.destination))}"`;
        if (node.title) s += ` title="${escapeHtml(node.title)}"`;
        this.out(s + '>');
        this.renderChildren(node);
        this.out('</a>');
        break;
      }
      case 'image': {
        let s = `<img src="${escapeHtml(safeUrl(node.destination))}" alt="${escapeHtml(plainText(node))}"`;
        if (node.title) s += ` title="${escapeHtml(node.title)}"`;
        this.out(s + ' />');
        break;
      }
      case 'wikilink': {
        const wl = this.options.wikiLinks;
        let exists = true;
        try { exists = !!(wl && typeof wl.exists === 'function' ? wl.exists(node.slug) : true); } catch { exists = false; }
        this.out(`<a href="/wiki/${escapeHtml(node.slug)}" class="wikilink${exists ? '' : ' missing'}">${escapeHtml(node.label)}</a>`);
        break;
      }
      default: this.renderChildren(node);
    }
  }

  renderTable(node) {
    const align = i => (node.aligns[i] ? ` align="${node.aligns[i]}"` : '');
    this.cr();
    this.out('<table>\n<thead>\n<tr>\n');
    node.headerNodes.forEach((cell, i) => { this.out(`<th${align(i)}>`); this.renderChildren(cell); this.out('</th>\n'); });
    this.out('</tr>\n</thead>\n');
    if (node.rowNodes.length) {
      this.out('<tbody>\n');
      for (const row of node.rowNodes) {
        this.out('<tr>\n');
        row.forEach((cell, i) => { this.out(`<td${align(i)}>`); this.renderChildren(cell); this.out('</td>\n'); });
        this.out('</tr>\n');
      }
      this.out('</tbody>\n');
    }
    this.out('</table>');
    this.cr();
  }
}

// --------------------------------------------------------------------- API

export function parse(markdown, options = {}) {
  return new BlockParser(options).parse(String(markdown ?? ''));
}

export function render(markdown, { headingIds = false, wikiLinks } = {}) {
  const doc = parse(markdown, { wikiLinks });
  const r = new HtmlRenderer({ headingIds, wikiLinks });
  r.render(doc);
  return r.buf;
}

function walk(node, fn) {
  fn(node);
  for (let c = node.firstChild; c; c = c.next) walk(c, fn);
  if (node.type === 'table') {
    for (const c of node.headerNodes || []) walk(c, fn);
    for (const r of node.rowNodes || []) for (const c of r) walk(c, fn);
  }
}

export function toc(markdown) {
  const doc = parse(markdown, {});
  const seen = new Map();
  const out = [];
  walk(doc, (n) => {
    if (n.type === 'heading') {
      const text = headingText(n);
      out.push({ level: n.level, text, slug: slugify(text, seen) });
    }
  });
  return out;
}

/** Distinct, sorted wiki-link target slugs in a document (code excluded). */
export function wikiLinkTargets(markdown) {
  const doc = parse(markdown, { wikiLinks: { exists: () => true } });
  const set = new Set();
  walk(doc, (n) => { if (n.type === 'wikilink' && n.slug) set.add(n.slug); });
  return [...set].sort();
}
